// Reduced from `solid-js@2.0.0-rc.3` `types/index.d.ts`. `createRoot`, `flush`,
// `onSettled`, `refresh` and `untrack` are re-exported from `@solidjs/signals`
// exactly as `types/index.d.ts:1` re-exports them. `createMemo`, `createSignal`
// and `createStore` are consts in `types/client/hydration.d.ts` whose call
// signatures repeat the signals overloads with hydration options, and
// `createEffect` is `typeof coreEffect`; the overloads these cases call return
// the same `SourceAccessor<T>`, `Signal<T>` and `[Store<T>, StoreSetter<T>]`,
// so the signals functions are re-exported directly here.
export { createRoot, flush, onSettled, refresh, untrack } from "@solidjs/signals";
export { createEffect, createMemo, createSignal, createStore } from "@solidjs/signals";
